CREATE TABLE categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE) STRICT;
CREATE TABLE products(id INTEGER PRIMARY KEY, name TEXT NOT NULL CHECK(length(name)>0), description TEXT NOT NULL DEFAULT '', brand TEXT NOT NULL DEFAULT '', category_id INTEGER REFERENCES categories(id), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1))) STRICT;
CREATE TABLE skus(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), internal_code TEXT NOT NULL UNIQUE CHECK(length(internal_code)>0), presentation TEXT NOT NULL DEFAULT '', purchase_cents INTEGER NOT NULL CHECK(purchase_cents>=0), sale_cents INTEGER NOT NULL CHECK(sale_cents>=0), default_pack INTEGER NOT NULL DEFAULT 1 CHECK(default_pack>0), expiry_control INTEGER NOT NULL DEFAULT 0 CHECK(expiry_control IN(0,1)), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1))) STRICT;
CREATE TABLE barcodes(sku_id INTEGER NOT NULL REFERENCES skus(id), code TEXT NOT NULL CHECK(length(code)>0), PRIMARY KEY(sku_id,code)) STRICT;
CREATE INDEX idx_barcodes_code ON barcodes(code);
CREATE INDEX idx_products_name ON products(name);
CREATE INDEX idx_products_category ON products(category_id);
CREATE TABLE suppliers(id INTEGER PRIMARY KEY, name TEXT NOT NULL CHECK(length(name)>0), tax_id TEXT NOT NULL DEFAULT '', contact TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1))) STRICT;
CREATE UNIQUE INDEX idx_supplier_document ON suppliers(tax_id) WHERE tax_id<>'';
CREATE TABLE receipts(id INTEGER PRIMARY KEY, supplier_id INTEGER REFERENCES suppliers(id), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','confirmed','canceled')), source TEXT NOT NULL DEFAULT 'manual' CHECK(source IN('manual','xml')), notes TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), confirmed_at TEXT) STRICT;
CREATE TABLE receipt_items(id INTEGER PRIMARY KEY, receipt_id INTEGER NOT NULL REFERENCES receipts(id), sku_id INTEGER REFERENCES skus(id), quantity TEXT NOT NULL, units_per_pack INTEGER NOT NULL CHECK(units_per_pack>0), units INTEGER CHECK(units>0), commercial_unit TEXT NOT NULL, unit_price TEXT NOT NULL, total_cents INTEGER NOT NULL CHECK(total_cents>=0), unit_cost_cents INTEGER CHECK(unit_cost_cents>=0), rounding_difference_cents INTEGER) STRICT;
CREATE INDEX idx_receipt_items_receipt ON receipt_items(receipt_id);
CREATE TABLE stock_movements(id INTEGER PRIMARY KEY, sku_id INTEGER NOT NULL REFERENCES skus(id), quantity INTEGER NOT NULL CHECK(quantity<>0 AND quantity BETWEEN -1000000000 AND 1000000000), kind TEXT NOT NULL CHECK(kind IN('receipt','issue','adjustment','inventory','reclassify')), origin_type TEXT NOT NULL, origin_id TEXT NOT NULL, origin_line INTEGER NOT NULL, reason TEXT NOT NULL, unit_cost_cents INTEGER NOT NULL CHECK(unit_cost_cents>=0), created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(origin_type,origin_id,origin_line)) STRICT;
CREATE INDEX idx_movements_sku ON stock_movements(sku_id);
CREATE INDEX idx_movements_date ON stock_movements(created_at);
CREATE TABLE stock_operations(request_key TEXT PRIMARY KEY, kind TEXT NOT NULL, reason TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))) STRICT;
CREATE TABLE operation_requests(request_key TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL) STRICT;
CREATE TABLE audit_events(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, entity_id TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))) STRICT;
CREATE TABLE app_settings(id INTEGER PRIMARY KEY CHECK(id=1), short_days INTEGER NOT NULL CHECK(short_days BETWEEN 0 AND 3650), long_days INTEGER NOT NULL CHECK(long_days>=short_days AND long_days<=3650)) STRICT;
INSERT INTO app_settings VALUES(1,7,30);
CREATE TRIGGER movements_immutable_update BEFORE UPDATE ON stock_movements BEGIN SELECT RAISE(ABORT,'AXIS:Movimentos confirmados não podem ser editados.'); END;
CREATE TRIGGER movements_immutable_delete BEFORE DELETE ON stock_movements BEGIN SELECT RAISE(ABORT,'AXIS:Movimentos confirmados não podem ser excluídos.'); END;
CREATE TRIGGER audit_immutable_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'AXIS:Auditoria imutável.'); END;
CREATE TRIGGER audit_immutable_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'AXIS:Auditoria imutável.'); END;
CREATE TRIGGER receipt_final BEFORE UPDATE ON receipts WHEN OLD.status<>'draft' BEGIN SELECT RAISE(ABORT,'AXIS:Recebimento já encerrado; use uma operação compensatória.'); END;
CREATE TRIGGER receipt_item_insert BEFORE INSERT ON receipt_items WHEN (SELECT status FROM receipts WHERE id=NEW.receipt_id)<>'draft' BEGIN SELECT RAISE(ABORT,'AXIS:Recebimento encerrado.'); END;
CREATE TRIGGER receipt_item_update BEFORE UPDATE ON receipt_items WHEN (SELECT status FROM receipts WHERE id=OLD.receipt_id)<>'draft' BEGIN SELECT RAISE(ABORT,'AXIS:Recebimento encerrado.'); END;
CREATE TRIGGER receipt_item_delete BEFORE DELETE ON receipt_items WHEN (SELECT status FROM receipts WHERE id=OLD.receipt_id)<>'draft' BEGIN SELECT RAISE(ABORT,'AXIS:Recebimento encerrado.'); END;
